import type { Lesson, Source, Step, Text } from './types';

const t = (uk: string, en: string): Text => ({ uk, en });
const s = (uk: string, en: string, bodyUk: string, bodyEn: string, checkUk?: string, checkEn?: string): Step => ({ title: t(uk, en), body: t(bodyUk, bodyEn), ...(checkUk && checkEn ? { check: t(checkUk, checkEn) } : {}) });
const q = (uk: string, en: string, options: Text[], correct: number, explanationUk: string, explanationEn: string): Lesson['quiz'] => ({ question: t(uk, en), options, correct, explanation: t(explanationUk, explanationEn) });
const serviceBoundary = t('Межі для новачка: огляд, записи й лише дозволені виробником операторські дії під наглядом. Розбирання, електрика, підшипники й сервісні корекції — робота кваліфікованого фахівця за документацією після перевіреної ізоляції всіх джерел енергії. E-stop не замінює ізоляцію.', 'Beginner scope: inspection, records and only manufacturer-permitted operator tasks under supervision. Dismantling, electrical work, bearings and service adjustments belong to a qualified technician following the documentation after verified isolation of all energy sources. E-stop does not replace isolation.');
const care = (lesson: Omit<Lesson, 'category'>): Lesson => ({ ...lesson, category: 'machine-care', hazards: [serviceBoundary, ...lesson.hazards] });
const tooling = (lesson: Omit<Lesson, 'category'>): Lesson => ({ ...lesson, category: 'tooling' });

