export const preparationLessons: Lesson[] = [
  care({
    id: 'machine-assessment', title: t('Чи готовий верстат до роботи?', 'Is the machine ready for use?'), summary: t('Відокремлюємо первинне введення в експлуатацію, плановий сервіс і щоденний огляд. Складаємо карту стану перед навчанням.', 'Separate commissioning, scheduled service and daily inspection. Build a condition record before learning to machine.'), minutes: 12, level: 'beginner', tags: [t('Підготовка верстата', 'Machine preparation'), t('Почніть тут', 'Start here')], prerequisites: ['safety-first', 'energy-isolation'],
    hazards: [t('Новий, уживаний або переміщений верстат не вважають готовим лише тому, що двигун запускається. Повне розбирання перед кожним використанням не потрібне й може порушити налаштування.', 'A new, used or relocated machine is not ready merely because the motor runs. Dismantling before every use is unnecessary and may destroy the setup.')],
    steps: [
      s('Встановіть ідентичність', 'Identify the machine', 'Запишіть виробника, модель, серійний номер, рік і контролер. Знайдіть документацію саме цієї комплектації, а не схожого верстата. Відсутню табличку або незрозумілу модифікацію внесіть у перелік питань.', 'Record maker, model, serial number, year and controller. Obtain documentation for this exact configuration rather than a similar machine. Log missing identification or unexplained modifications.'),
      s('Визначте тип підготовки', 'Choose the preparation category', 'Після доставки, тривалого зберігання, аварії чи ремонту потрібне приймання фахівцем. Для вже прийнятого справного верстата діють щоденні перевірки та регламентний сервіс, а не повторне повне розбирання.', 'Delivery, long storage, a crash or repair requires qualified acceptance. An already accepted sound machine needs daily checks and scheduled service rather than repeated complete dismantling.'),
      s('Зберіть історію стану', 'Collect condition history', 'Перегляньте журнал мастила, ремонтів, несправностей і перевірки геометрії. З’ясуйте, чи був удар по шпинделю, затоплення або перегрів. Невідомий ремонт позначайте як невизначеність, а не як підтвердження справності.', 'Review lubrication, repair, fault and geometry records. Check for spindle impact, flooding or overheating. Treat undocumented repairs as uncertainty rather than proof of sound condition.'),
      s('Зробіть безпечний зовнішній огляд', 'Make a safe external inspection', 'Без запуску перевірте доступні огородження, кабелі, витоки, корозію й відсутні деталі. Не знімайте кришки та не переміщуйте підозріло заклинені вузли силою. Фото й точний опис корисніші за спробу «розходити» механізм.', 'Without starting, inspect accessible guards, cables, leaks, corrosion and missing parts. Do not remove covers or force suspected binding. Photos and an accurate description are more useful than trying to free it by force.'),
      s('Розділіть завдання за відповідальністю', 'Assign responsibilities', 'У карті стану відокремте операторське очищення, дозволене змащування та перевірку від сервісного демонтажу, регулювання опор і електрики. Для кожного завдання вкажіть виконавця, посилання на OEM і безпечний стан.', 'In the condition record, separate operator cleaning, permitted lubrication and checks from dismantling, bearing work and electrical service. Give each task an owner, OEM reference and required safe state.'),
      s('Прийміть рішення до запуску', 'Decide before starting', 'Оберіть статус: допущений із визначеними обмеженнями, очікує перевірки або виведений із роботи. За відсутніх захистів, невідомого мастила, пошкоджень чи непоясненого шуму — зупинка й повідомлення відповідальному.', 'Assign a status: accepted with defined limits, awaiting inspection or out of service. Missing guards, unknown lubrication, damage or unexplained noise mean stop and notify the responsible person.'),
      s('Зафіксуйте підставу допуску', 'Record the basis for acceptance', 'Внесіть дату, особу, усунені дефекти та результати перевірок. Наставник починає навчання лише в межах підтверджених можливостей верстата. Після нової несправності попередній допуск переглядають.', 'Record date, responsible person, corrected defects and verification results. Begin training only within the machine’s confirmed capabilities. Review acceptance after a new fault.', 'Статус і відповідальна людина визначені; невідомі ризики не приховані.', 'Status and responsibility are assigned; unknown risks are not concealed.'),
    ], takeaways: [t('Справний двигун не доводить справності верстата.', 'A working motor does not prove a sound machine.'), t('Підготовка має відповідати події: щоденний огляд, плановий сервіс або повторне приймання.', 'Preparation must match the event: daily inspection, scheduled service or renewed acceptance.')], sources: ['prep-haas-maintenance', 'prep-haas-service', 'ccohs-general'],
    quiz: q('Що потрібно перед роботою на давно невідомо як обслуговуваному верстаті?', 'What is required before using a machine with an unknown maintenance history?', [t('Пробне різання на високих обертах', 'A high-speed trial cut'), t('Оцінка стану й підтвердження готовності компетентною людиною', 'Condition assessment and readiness confirmation by a competent person'), t('Повне самостійне розбирання новачком', 'Complete dismantling by the beginner')], 1, 'Історію та стан перевіряють до запуску; масштаб сервісу визначають за результатом, документацією й кваліфікацією.', 'Check history and condition before starting; determine service scope from findings, documentation and competence.'),
  }),
  care({
    id: 'daily-inspection', title: t('Щоденний огляд перед зміною', 'Daily pre-shift inspection'), summary: t('Коротка перевірка вже прийнятого верстата: захисти, мастило, рухи, робоча зона та журнал відхилень.', 'Check an already accepted machine: guards, lubrication, motion, workspace and deviation records.'), minutes: 9, level: 'beginner', tags: [t('Щодня', 'Daily'), t('Огляд', 'Inspection')], prerequisites: ['machine-assessment'],
    hazards: [t('Щоденний огляд не дозволяє відкривати електрику, обходити блокування або випробовувати відомо несправний механізм.', 'Daily inspection does not authorize opening electrical equipment, bypassing interlocks or testing a known faulty mechanism.')],
    steps: [
      s('Прочитайте передачу зміни', 'Read the handover', 'Перевірте статус верстата, записи попередньої зміни й незакриті несправності. Якщо обладнання заблоковане або позначене як несправне, не знімайте маркування й не запускайте його.', 'Check machine status, previous-shift notes and unresolved faults. If the machine is locked or marked out of service, do not remove identification or start it.'),
      s('Огляньте без живлення там, де потрібно', 'Inspect in the required safe state', 'До доступу в небезпечну зону застосуйте встановлену процедуру ізоляції. Зовні перевірте скло, захисти, кабелі, сліди витоку й сторонні предмети. Аварійна кнопка сама по собі не створює безпечного доступу.', 'Before entering a hazard zone, apply the established isolation procedure. Externally inspect windows, guards, cables, leaks and loose objects. An emergency button alone does not make access safe.'),
      s('Перевірте рівні та термін сервісу', 'Check levels and service status', 'Звірте доступні покажчики мастила й охолоджувальної рідини з OEM. Нормальний рівень не доводить подачі до вузлів. За тривоги змащування не доливайте випадкову рідину й не продовжуйте роботу.', 'Compare accessible lubrication and coolant indicators with the OEM requirements. A normal reservoir level does not prove delivery. Do not add arbitrary fluid or continue through a lubrication alarm.'),
      s('Перевірте кріплення й чистоту', 'Check workholding and cleanliness', 'Переконайтеся, що стіл, патрон і тримачі чисті, а оснащення не пошкоджене. Після зміни встановлення повторіть повну перевірку затиску, ключів, зазорів і доступу до стопа.', 'Check that table, chuck and holders are clean and undamaged. After any setup change, repeat the complete workholding, key-removal, clearance and stop-access checks.'),
      s('Виконайте лише дозволені функціональні перевірки', 'Perform only approved functional checks', 'Штатні тести захистів, зупинки, прогріву та рухів виконуйте в послідовності OEM з наставником і без людей у зоні. Не перевіряйте блокування обхідним способом і не ігноруйте незвичний опір.', 'Perform OEM-defined guard, stop, warm-up and motion tests with a supervisor and personnel clear. Never test interlocks by defeating them or ignore unusual resistance.'),
      s('Запишіть відхилення й рішення', 'Record deviations and disposition', 'Записуйте конкретно: місце витоку, код тривоги, напрямок тугого руху, момент появи шуму. За відхилення зупиніть роботу, повідомте відповідальному й дочекайтеся дозволу після усунення причини.', 'Record specifics: leak location, alarm code, direction of stiffness and when noise occurs. Stop for deviations, notify the responsible person and await release after the cause is resolved.', 'Огляд записаний; відкритих небезпечних дефектів немає.', 'Inspection is recorded and no hazardous defect remains open.'),
    ], takeaways: [t('Щоденний огляд шукає зміни від прийнятого стану.', 'Daily inspection detects changes from the accepted baseline.'), t('Порожня клітинка в журналі не означає успішної перевірки.', 'An empty log field does not mean a check passed.')], sources: ['prep-haas-maintenance', 'prep-haas-desktop', 'ccohs-general'],
    quiz: q('Резервуар повний, але є тривога змащування. Що робити?', 'The reservoir is full but a lubrication alarm is active. What should you do?', [t('Продовжувати, бо мастило видно', 'Continue because oil is visible'), t('Зупинитися й повідомити про можливу проблему подачі', 'Stop and report a possible delivery problem'), t('Відключити тривогу', 'Disable the alarm')], 1, 'Рівень рідини не підтверджує працездатності насоса, розподільників або каналів.', 'Fluid level does not establish pump, distribution or passage function.'),
  }),
  care({
    id: 'cleaning-lubrication', title: t('Очищення, консервація та змащування', 'Cleaning, protection and lubrication'), summary: t('Прибираємо стружку й консерваційне покриття дозволеним способом, не заганяючи абразив у напрямні.', 'Remove chips and protective coating by approved methods without driving abrasive debris into slideways.'), minutes: 12, level: 'beginner', tags: [t('Змащування', 'Lubrication'), t('Очищення', 'Cleaning')], prerequisites: ['daily-inspection', 'chips-fire'],
    hazards: [t('Розчинники можуть бути горючими й токсичними. Не використовуйте бензин або невідомі суміші; не розпилюйте рідину на двигуни й електрику.', 'Solvents may be flammable and hazardous. Do not use gasoline or unidentified mixtures; do not spray fluid on motors or electrical equipment.'), t('Змащувач, антикорозійний засіб і охолоджувальна рідина мають різні функції та не є взаємозамінними.', 'Lubricant, rust protection and coolant serve different purposes and are not interchangeable.')],
    steps: [
      s('Визначте стан і продукт', 'Identify the task and product', 'Розділіть щоденне очищення, видалення транспортного консерванту й сервісне промивання. За OEM визначте дозволений засіб, тип мастила, точки та періодичність; перевірте SDS.', 'Separate daily cleaning, shipping-protectant removal and service flushing. Use the OEM to identify approved cleaner, lubricant, locations and intervals; check the SDS.'),
      s('Забезпечте безпечний доступ', 'Secure safe access', 'Повністю зупиніть рух і виконайте потрібну ізоляцію з перевіркою. Дочекайтеся охолодження стружки. Захисні рукавички для окремої роботи з нерухомими гострими відходами зніміть до відновлення обертання.', 'Fully stop motion and apply the required verified isolation. Allow chips to cool. Remove any gloves used for a separate stationary sharp-waste task before restoring rotation.'),
      s('Зберіть стружку без розсіювання', 'Collect chips without dispersion', 'Використайте щітку, гачок або схвалену для матеріалу систему. Не здувайте стружку повітрям і не проштовхуйте її під ущільнення. Не протирайте напрямні брудною ганчіркою зі стружкою.', 'Use a brush, hook or material-approved collection system. Do not blow chips with air or drive them under seals. Never wipe slideways with a chip-contaminated rag.'),
      s('Обережно приберіть захисне покриття', 'Remove protective coating carefully', 'Якщо OEM вимагає видалення консерванту перед рухом, виконайте саме цю процедуру. Не застосовуйте абразивні губки, наждак чи металевий скребок до прецизійних поверхонь без прямого дозволу виробника.', 'If the OEM requires protectant removal before movement, follow that procedure. Do not use abrasive pads, emery or metal scrapers on precision surfaces without explicit manufacturer approval.'),
      s('Змастіть лише визначені місця', 'Lubricate only specified locations', 'Користуйтеся підписаною чистою тарою й дозуванням OEM. Не змішуйте невідомі мастила й не перевищуйте об’єм. Втручання в насос, дозатори, шпиндельні опори або приховані канали передайте сервісу.', 'Use labeled clean containers and OEM quantities. Do not mix unknown lubricants or overfill. Leave pump, metering, spindle-bearing or concealed-passage work to service personnel.'),
      s('Перевірте результат і відходи', 'Check the result and waste', 'Огляньте доступні поверхні, прибрані інструменти та відсутність калюж. Уповноважена людина підтверджує подачу мастила визначеним методом. Запишіть продукт і дату; забруднені відходи утилізуйте за правилами.', 'Inspect accessible surfaces, tool clearance and absence of spills. An authorized person verifies lubricant delivery by the prescribed method. Record product and date and dispose of contaminated waste correctly.', 'Продукт і точки змащування відповідають OEM; зону прибрано.', 'Lubricant and locations match the OEM; the area is clean.'),
    ], takeaways: [t('Чистота перед змащуванням важливіша за додавання більшої кількості мастила.', 'Cleaning before lubrication matters more than adding extra lubricant.'), t('Сухе місце або повторна тривога — привід зупинитися, а не вгадувати склад мастила.', 'A dry location or recurring alarm calls for stopping, not guessing a lubricant.')], sources: ['prep-haas-desktop', 'prep-sherline-manual', 'ccohs-general'],
    quiz: q('Чи можна замінити вказане мастило антикорозійним спреєм?', 'Can the specified lubricant be replaced by a rust-prevention spray?', [t('Так, усі маслянисті засоби однакові', 'Yes, all oily products are equivalent'), t('Лише за прямою сумісною вказівкою OEM', 'Only when explicitly approved as compatible by the OEM'), t('Так, якщо нанести більше', 'Yes, if more is applied')], 1, 'Призначення, в’язкість і сумісність визначаються виробником вузла.', 'The component manufacturer defines purpose, viscosity and compatibility.'),
  }),
  care({
    id: 'machine-installation', title: t('Встановлення та введення в експлуатацію', 'Installation and commissioning'), summary: t('Основа, опори, переміщення, підключення й приймання геометрії перед першою роботою.', 'Plan the foundation, supports, handling, connections and geometric acceptance before first use.'), minutes: 14, level: 'intermediate', tags: [t('Встановлення', 'Installation'), t('Приймання', 'Acceptance')], prerequisites: ['machine-assessment', 'cleaning-lubrication'],
    hazards: [t('Підйом важкого верстата, робота під піднятим вузлом і підключення живлення — не завдання для самостійного новачка. Застосовують план підйому й кваліфікованих виконавців.', 'Lifting a heavy machine, working beneath raised components and connecting power are not independent beginner tasks. Use a lifting plan and qualified personnel.')],
    steps: [
      s('Перевірте місце встановлення', 'Verify the installation site', 'За схемою OEM перевірте масу, габарити, вимоги до основи, проходів і доступу для сервісу. Побутовий стіл або випадкова плита не підтверджують несучої здатності й стійкості.', 'Use the OEM plan to verify mass, envelope, foundation, access and service clearances. A domestic bench or arbitrary slab does not establish load capacity or stability.'),
      s('Організуйте безпечне переміщення', 'Arrange safe handling', 'Кваліфікована команда обирає точки стропування, обладнання та маршрут. Не піднімайте верстат за стіл, шпиндель, маховики або інші зручні виступи без прямої вказівки OEM; тримайте людей поза зоною вантажу.', 'A qualified team selects lifting points, equipment and route. Do not lift by the table, spindle, handwheels or convenient projections unless explicitly specified by the OEM; keep people clear of the load.'),
      s('Підготуйте транспортні елементи', 'Address shipping fixtures', 'За документацією визначте консервацію, транспортні стопори й опори. Їх зняття та збирання виконує призначений виконавець у потрібній послідовності; випадковий болт може бути не транспортним.', 'Identify protectant, transport locks and supports from the documentation. A designated person removes and assembles them in the required sequence; an unfamiliar bolt may not be a shipping fastener.'),
      s('Перевірте комунікації фахівцем', 'Have services checked by specialists', 'Електрик підтверджує відповідність живлення, заземлення й захисту; уповноважені працівники — пневматики, гідравліки та охолодження. Новачок фіксує документи, не вимірює напругу у відкритій шафі.', 'An electrician verifies supply, protective earth and protection; authorized personnel verify air, hydraulics and cooling. A beginner records the documents rather than measuring voltage in an open cabinet.'),
      s('Виставте опори за процедурою', 'Set supports under the procedure', 'Сервіс перевіряє рівень, скручування станини й навантаження опор із придатним каліброваним рівнем. Не підкладайте випадкові матеріали та не затягуйте анкери «до упору»: це може спотворити геометрію.', 'Service personnel check level, bed twist and support loading with a suitable calibrated level. Do not add arbitrary shims or tighten anchors to an assumed maximum; this can distort geometry.'),
      s('Проведіть приймальні перевірки', 'Complete acceptance checks', 'За OEM виконують перевірки захистів, змащування, рухів, шпинделя та потрібної геометрії. Прогрів і обкатка застосовуються лише за відповідною програмою; дефекти не маскують різанням.', 'Follow the OEM acceptance checks for guards, lubrication, axes, spindle and required geometry. Use warm-up or run-in only under the applicable procedure; do not mask faults by cutting.'),
      s('Передайте верстат із записами', 'Handover with records', 'Збережіть результати, допустимі межі, дату й відповідального. За невідповідності верстат залишається поза роботою. Після переміщення, значного ремонту чи удару визначте обсяг повторного приймання.', 'Retain results, limits, date and responsible person. Keep the machine out of service for nonconformity. Define reacceptance scope after relocation, major repair or impact.', 'Є приймальний запис; електрика й геометрія підтверджені виконавцями.', 'Acceptance is recorded; qualified personnel confirmed electrical and geometric condition.'),
    ], takeaways: [t('Рівна підлога не гарантує нескрученої станини.', 'A level floor does not guarantee an untwisted bed.'), t('Введення в експлуатацію — окрема подія з відповідальністю та результатами.', 'Commissioning is a distinct event with responsibility and recorded results.')], sources: ['prep-haas-installation', 'prep-haas-service', 'osha-loto'],
    quiz: q('Хто підключає й перевіряє силове живлення?', 'Who connects and verifies the power supply?', [t('Новачок за фото в інтернеті', 'A beginner using an internet photo'), t('Кваліфікований електротехнічний фахівець за документацією', 'A qualified electrical specialist following the documentation'), t('Будь-хто, якщо E-stop натиснутий', 'Anyone if E-stop is pressed')], 1, 'Силова електрика потребує спеціальної кваліфікації та перевіреної процедури.', 'Power electrical work requires specific competence and a verified procedure.'),
  }),
  care({
    id: 'slideways-gibs', title: t('Напрямні та регулювальні клини', 'Slideways and gibs'), summary: t('Відрізняємо хитання супорта від тугого ходу, оцінюємо стан напрямних і межі дозволеного регулювання.', 'Separate slide rocking from stiff travel and assess slideway condition and permitted adjustment.'), minutes: 14, level: 'intermediate', tags: [t('Напрямні', 'Slideways'), t('Клини', 'Gibs')], prerequisites: ['cleaning-lubrication', 'dial-indicator'], model: 'lathe',
    hazards: [t('Перетягнутий клин може заклинити вісь, перевантажити привід і прискорити знос. Клин не виправляє викривлені, пошкоджені або нерівномірно зношені напрямні.', 'An overtightened gib can bind an axis, overload the drive and accelerate wear. A gib cannot repair distorted, damaged or unevenly worn slideways.')],
    steps: [
      s('Розпізнайте вузол', 'Identify the assembly', 'За схемою саме вашого верстата знайдіть напрямні, клин, фіксатори й кінцеві обмеження. Не приймайте гвинт кріплення або стопор за регулювання; конструкції клинів відрізняються.', 'Use the exact machine drawing to identify ways, gib, locks and travel limits. Do not mistake a mounting or locking screw for an adjuster; gib designs differ.'),
      s('Очистіть і зафіксуйте вихідний стан', 'Clean and record the baseline', 'Після перевіреної ізоляції очистіть доступні напрямні й застосуйте вказане мастило. Запишіть, де рух тугий, де є хитання й чи змінюється симптом уздовж ходу. Не шліфуйте прецизійні поверхні.', 'After verified isolation, clean accessible ways and apply the specified lubricant. Record stiffness, rocking and how symptoms change along travel. Do not abrade precision surfaces.'),
      s('Відокремте люфт напрямної від гвинта', 'Separate way play from screw backlash', 'Під наглядом виконайте дозволену ручну перевірку індикатором на жорсткій базі. Хитання поперек напрямної та мертвий хід при реверсі гвинта — різні явища; не усувайте їх одним випадковим гвинтом.', 'Under supervision, perform the approved manual indicator check from a rigid base. Rocking across a guide and lost motion on screw reversal are different effects; do not address both by turning an arbitrary screw.'),
      s('Визначте, хто й що може регулювати', 'Determine the permitted adjustment', 'Якщо OEM прямо описує зовнішнє операторське регулювання, його виконує навчений оператор із наставником. Приховані вузли, демонтаж, підгонка, шабрування або незрозуміла схема потребують сервісного фахівця.', 'Where the OEM explicitly permits an external operator adjustment, a trained operator performs it with supervision. Concealed assemblies, dismantling, fitting, scraping or unclear designs require a service technician.'),
      s('Перевірте весь дозволений хід', 'Check the complete permitted travel', 'Після корекції відповідальний перевіряє плавність і виміряний люфт у кількох положеннях, зокрема на менш зношених кінцях. Значення, порядок гвинтів і моменти беруть із OEM; універсального «затягнути без люфту» немає.', 'After adjustment, the responsible person checks smooth travel and measured play at several locations, including less-worn ends. Use OEM values, screw sequence and torques; there is no universal tighten-until-zero rule.'),
      s('Зупиніться за суперечливого результату', 'Stop for conflicting results', 'Якщо середина рухається добре, а край заклинює, не шукайте компроміс навмання. Виведіть вузол із роботи й передайте карту вимірів сервісу. Після приймання запишіть результат і повторну геометричну перевірку.', 'If the middle moves well but an end binds, do not hunt for an arbitrary compromise. Take the assembly out of service and give the measurement map to service personnel. Record acceptance and geometric recheck afterward.', 'Плавність і люфт перевірені по ходу, а межі OEM виконані.', 'Smoothness and play are checked across travel and OEM limits are met.'),
    ], takeaways: [t('Клин задає контакт напрямних, а не компенсує знос ходової гайки.', 'A gib controls guide contact; it does not compensate for leadscrew-nut wear.'), t('Підгонка й шабрування — кваліфікована ремонтна робота.', 'Fitting and scraping are skilled repair operations.')], sources: ['prep-sherline-manual', 'prep-sherline-videos', 'mitutoyo-indicator'],
    quiz: q('Після підтягування клина кінець ходу заклинює. Що робити?', 'After gib adjustment, an end of travel binds. What should you do?', [t('Додати силу або потужність приводу', 'Apply more force or drive power'), t('Зупинитися й передати результати фахівцю', 'Stop and refer the findings to a technician'), t('Продовжити лише в центрі без запису', 'Use only the middle without recording the fault')], 1, 'Нерівномірний хід може вказувати на знос, забруднення або помилку геометрії; силове переміщення погіршує стан.', 'Uneven travel may indicate wear, contamination or geometric error; forcing it can worsen the condition.'),
  }),
  care({
    id: 'backlash-leadscrews', title: t('Люфт гвинта, гайки та маховика', 'Backlash in screws, nuts and handwheels'), summary: t('Вимірюємо мертвий хід при зміні напрямку та шукаємо джерело без небезпечної вимоги нульового люфту.', 'Measure reversal lost motion and identify its source without demanding unsafe zero backlash.'), minutes: 14, level: 'intermediate', tags: [t('Люфт', 'Backlash'), t('Ходовий гвинт', 'Leadscrew')], prerequisites: ['slideways-gibs'], model: 'lathe',
    hazards: [t('Нульовий люфт за тугого, заклиненого вузла не є правильним налаштуванням. Попередній натяг опор, кулькової гайки та параметри сервоприводу регулює лише кваліфікований сервіс.', 'A zero reading from a stiff or bound assembly is not a correct adjustment. Bearing preload, ballscrew-nut preload and servo parameters require qualified service.')],
    steps: [
      s('Визначте тип приводу', 'Identify the drive type', 'З’ясуйте, чи стоїть звичайний ходовий гвинт, розрізна гайка, кулькогвинтова передача або інший механізм. Норми й метод регулювання однієї конструкції не переносять на іншу.', 'Identify a conventional leadscrew, split nut, ballscrew or another mechanism. Do not transfer one design’s limits or adjustment method to another.'),
      s('Створіть безпечне вимірювальне встановлення', 'Prepare a safe measuring setup', 'За ізольованого приводу й дозволеного ручного переміщення закріпіть індикатор від нерухомої бази до потрібної осі. Вертикальні вузли мають бути убезпечені від падіння; не відкручуйте їхні опори.', 'With the drive isolated and manual movement permitted, mount an indicator from a fixed reference to the axis. Secure vertical assemblies against falling; do not release their supports.'),
      s('Виміряйте реверс у кількох місцях', 'Measure reversal at several positions', 'Навчений оператор підходить в одному напрямку, фіксує відлік і змінює напрямок до підтвердженого початку руху індикатора. Запишіть мертвий хід, одиниці та місце; врахуйте діаметральне або радіальне градуювання лімба.', 'A trained operator approaches in one direction, records a reference and reverses until indicator movement is confirmed. Record lost motion, units and position; account for radius- or diameter-reading dials.'),
      s('Розділіть можливі джерела', 'Separate possible sources', 'Люфт може походити від кріплення маховика, осьового ходу гвинта, гайки або напрямних. Без розбирання запишіть спостереження; не затягуйте опору шпинделя чи гвинта лише через показ лімба.', 'Lost motion may come from handwheel mounting, screw endplay, the nut or the ways. Record accessible observations without dismantling; do not tighten bearings based only on a dial reading.'),
      s('Застосуйте лише документоване рішення', 'Use only a documented remedy', 'Дозволене OEM зовнішнє регулювання виконує навчена людина, потім перевіряє плавність по всьому ходу. Зношені гвинти й гайки ремонтує сервіс. Програмна компенсація ЧПУ не усуває механічної нестійкості.', 'A trained person performs any OEM-permitted external adjustment and checks smooth travel throughout. Service personnel repair worn screws and nuts. CNC compensation does not remove mechanical instability.'),
      s('Підтвердіть спосіб роботи або зупинку', 'Confirm the operating method or stop', 'Для прийнятого ручного верстата наставник визначає підхід до розміру з одного напрямку й безпечний тип фрезерування. За надмірного або змінного люфту, стрибків чи заклинювання — зупинка й повторне приймання після ремонту.', 'For an accepted manual machine, the supervisor defines same-direction positioning and a suitable milling strategy. Excessive or varying backlash, jumps or binding require stopping and reacceptance after repair.', 'Є карта люфту й дозволена стратегія, а не припущення про нуль.', 'A backlash map and permitted strategy exist rather than an assumed zero.'),
    ], takeaways: [t('Люфт вимірюють окремо від пружного відгину й хитання напрямних.', 'Measure backlash separately from elastic deflection and guide rocking.'), t('Число компенсації не замінює справної механіки.', 'A compensation number cannot replace sound mechanics.')], sources: ['prep-sherline-manual', 'prep-sherline-videos', 'mitutoyo-indicator'],
    quiz: q('Чи виправляє програмна компенсація люфту зношене кріплення?', 'Does software backlash compensation repair worn mechanical mounting?', [t('Так, повністю', 'Yes, completely'), t('Ні, механічну причину перевіряють і усувають окремо', 'No, inspect and remedy the mechanical cause separately'), t('Так, якщо збільшити компенсацію', 'Yes, if compensation is increased')], 1, 'Корекція координат не створює жорсткості й не запобігає некерованому переміщенню під силою різання.', 'Coordinate correction does not create rigidity or prevent uncontrolled movement under cutting load.'),
  }),
  care({
    id: 'spindle-condition', title: t('Стан шпинделя та його посадок', 'Spindle and interface condition'), summary: t('Розділяємо забруднений тримач, биття інструмента й можливу несправність шпиндельного вузла.', 'Separate a contaminated holder, tool runout and a possible spindle-assembly fault.'), minutes: 13, level: 'intermediate', tags: [t('Шпиндель', 'Spindle'), t('Биття', 'Runout')], prerequisites: ['daily-inspection', 'dial-indicator'],
    hazards: [t('Не регулюйте натяг шпиндельних підшипників, не вибивайте конус і не розбирайте шпиндель для усунення шуму. Це сервісна процедура з ризиком пошкодження й втрати утримання інструмента.', 'Do not adjust spindle-bearing preload, hammer out a taper or dismantle a spindle to cure noise. This is service work with damage and tool-retention risks.')],
    steps: [
      s('Зберіть опис симптому', 'Describe the symptom', 'Запишіть, чи був удар, який інструмент стояв, коли з’явилися шум, нагрів або биття. Відомо пошкоджений шпиндель не запускайте для демонстрації звуку.', 'Record any impact, installed tool and when noise, heating or runout appeared. Do not restart a known damaged spindle just to demonstrate its sound.'),
      s('Огляньте доступні посадки', 'Inspect accessible interfaces', 'Після ізоляції перевірте доступну посадку, тримач і контактні поверхні за OEM. Приберіть дозволеним засобом бруд; вм’ятини, задири й корозію сфотографуйте. Не виправляйте конус наждаком або напилком.', 'After isolation, inspect accessible seats, holder and contact surfaces under the OEM procedure. Remove dirt by approved methods and photograph dents, scoring or corrosion. Never dress a taper with emery or a file.'),
      s('Перевірте сумісність оснащення', 'Check tooling compatibility', 'Зіставте тип конуса, тяговий елемент, цангу, гайку та розміри з документацією. Схожий конус або різьба не гарантують сумісності; пошкоджене оснащення вилучіть.', 'Match taper type, retention component, collet, nut and dimensions to the documentation. Similar appearance or thread does not ensure compatibility; remove damaged tooling from service.'),
      s('Залучіть правильний вимірювальний метод', 'Use the correct measurement method', 'Кваліфікована людина перевіряє биття потрібної контрольної поверхні або еталонної оправки за OEM. Записують положення, відстань від носа й повторюваність; довільний хвостовик свердла не є еталоном шпинделя.', 'A qualified person checks the specified surface or test arbor under the OEM method. Record location, distance from the nose and repeatability; an arbitrary drill shank is not a spindle reference.'),
      s('Не змішуйте діагностику з пробним запуском', 'Separate diagnosis from trial running', 'Прогрів чи функціональний запуск виконують лише після дозволу для справного або прийнятого вузла, із захистами й визначеною програмою. Вібраційні тести, утримання інструмента та опори перевіряє сервіс.', 'Run warm-up or functional tests only after release for a sound or accepted assembly, with guards and a defined procedure. Leave vibration testing, retention checks and bearings to service personnel.'),
      s('Зафіксуйте допуск або заборону', 'Record release or prohibition', 'Порівняйте дані з нормою саме цього шпинделя й оснащення. За пошкодженої посадки, нового шуму, нагріву, втрати затиску або нестійких показів — не працюйте до висновку сервісу.', 'Compare findings with the limits for this spindle and tooling. Do not use it with damaged seats, new noise, heating, loss of retention or unstable readings until service has released it.', 'Стан оцінений за OEM, небезпечне оснащення вилучене.', 'Condition is assessed against OEM requirements and unsafe tooling removed.'),
    ], takeaways: [t('Биття на інструменті містить похибки шпинделя, тримача, цанги й самого інструмента.', 'Tool runout includes spindle, holder, collet and tool contributions.'), t('Сервіс опор потребує визначеної методики, а не підтискання до зникнення шуму.', 'Bearing service requires a defined method, not tightening until noise disappears.')], sources: ['prep-haas-maintenance', 'prep-haas-installation', 'tool-sandvik-holders'],
    quiz: q('Чи доводить биття свердла несправність підшипників шпинделя?', 'Does drill runout prove spindle-bearing failure?', [t('Так, без інших перевірок', 'Yes, without further checks'), t('Ні, потрібно розділити вплив інструмента, тримача, посадок і шпинделя', 'No, separate tool, holder, interface and spindle effects'), t('Ні, достатньо підшліфувати конус', 'No, simply grind the taper by hand')], 1, 'Вимірювальний ланцюг містить кілька елементів; ремонт починають із діагностики.', 'The measurement chain has several elements; diagnosis precedes repair.'),
  }),
  care({
    id: 'machine-alignment', title: t('Вирівнювання станини, головки й задньої бабки', 'Align the bed, head and tailstock'), summary: t('Розуміємо, що перевіряють рівнем та індикатором і чому різні осі потребують окремих перевірок.', 'Understand level and indicator checks and why each relationship needs its own verification.'), minutes: 16, level: 'advanced', tags: [t('Вивіряння', 'Alignment'), t('Геометрія', 'Geometry')], prerequisites: ['machine-installation', 'slideways-gibs', 'spindle-condition'], model: 'lathe',
    hazards: [t('Послаблення головки, колони або задньої бабки може вивільнити важкий вузол. Регулювання виконує кваліфікована людина з передбаченим утриманням і процедурою OEM.', 'Releasing a head, column or tailstock can free a heavy assembly. A qualified person performs adjustment with the specified support and OEM procedure.')],
    steps: [
      s('Визначте, який зв’язок потрібний', 'Identify the required relationship', 'Розділіть горизонтальність основи, скручування станини, перпендикулярність шпинделя до столу та співвісність задньої бабки. Успіх однієї перевірки не підтверджує решту.', 'Separate base level, bed twist, spindle-to-table squareness and tailstock coaxiality. Passing one check does not establish the others.'),
      s('Підготуйте правильні еталони', 'Prepare suitable references', 'Визначте калібрований рівень, індикатор, еталонну оправку або інший засіб за OEM. Очистіть бази, стабілізуйте температуру й перевірте повторюваність; звичайний будівельний рівень може бути непридатним.', 'Select a calibrated precision level, indicator, test arbor or other reference under the OEM. Clean datums, stabilize temperature and check repeatability; a construction level may be unsuitable.'),
      s('Перевірте основу перед вузлами', 'Check the foundation before assemblies', 'Сервіс спочатку підтверджує опори, закріплення та відсутність скручування. Не компенсуйте неправильне встановлення довільним поворотом головки: причину й наслідок потрібно розділити.', 'Service personnel first confirm supports, anchoring and absence of twist. Do not compensate for poor installation by arbitrarily rotating the head; separate cause and effect.'),
      s('Складіть карту вимірювань', 'Build a measurement map', 'Кваліфікований виконавець вимірює визначені точки й записує відстані та напрямки. Для фрезерного перевіряють потрібні положення шпинделя й столу; для токарного — вісь та задню бабку за обраним методом.', 'A qualified person measures defined points and records distances and directions. For milling, check the required spindle/table relationships; for turning, check the axis and tailstock under the selected method.'),
      s('Виконайте корекцію за встановленим порядком', 'Correct in the specified sequence', 'Навантаження опор, болти, регулювальні поверхні та моменти визначає OEM. Не використовуйте фольгу чи випадкові підкладки в прецизійних стиках і не шабруйте їх без сервісного проєкту.', 'The OEM defines support loads, fasteners, adjustment surfaces and torques. Do not add foil or arbitrary shims to precision joints or scrape them without a service plan.'),
      s('Повторіть перевірку після затягування', 'Recheck after final tightening', 'Затягування й зміна положення можуть змінити покази. Повторіть повний погоджений набір після фіксації; пробна деталь під наглядом може доповнити, але не замінити геометричний контроль.', 'Tightening and position changes can alter readings. Repeat the complete agreed set after securing; a supervised test piece may supplement but does not replace geometric checks.'),
      s('Видайте протокол і умови повторення', 'Issue the report and recheck triggers', 'Запишіть результати, допустимі межі та залишкові обмеження. За нестійких показів, потреби надмірної корекції або повторного розходження — зупинка й сервіс. Після удару чи перенесення повторіть оцінку.', 'Record results, limits and remaining restrictions. Stop and refer to service for unstable readings, excessive required correction or recurring misalignment. Reassess after impact or relocation.', 'Є протокол вимірювань після остаточної фіксації.', 'A measurement report exists after final securing.'),
    ], takeaways: [t('Горизонтальний стіл не доводить перпендикулярності шпинделя.', 'A level table does not prove spindle squareness.'), t('Задня бабка може мати бічну та висотну похибки, що перевіряються визначеним методом.', 'A tailstock can have lateral and height errors requiring a defined inspection method.')], sources: ['prep-haas-installation', 'prep-sherline-manual', 'mitutoyo-indicator'],
    quiz: q('Чи достатньо виставити верстат будівельним рівнем для підтвердження геометрії?', 'Is setting a machine with a construction level enough to confirm its geometry?', [t('Так, для будь-якого верстата', 'Yes, for any machine'), t('Ні, потрібні придатні еталони та окремі перевірки геометричних зв’язків', 'No, suitable references and separate geometric checks are required'), t('Так, якщо ніжки однакової довжини', 'Yes, if the feet have equal lengths')], 1, 'Рівень вимірює нахил, а не всі взаємні осі й поверхні верстата.', 'A level measures inclination, not every relationship between machine axes and surfaces.'),
  }),
  care({
    id: 'geometry-verification', title: t('Перевірка геометрії та точності переміщень', 'Verify geometry and positioning accuracy'), summary: t('Створюємо протокол: прямолінійність, перпендикулярність, повторюваність і похибка позиціонування — різні характеристики.', 'Create a report separating straightness, squareness, repeatability and positioning error.'), minutes: 15, level: 'advanced', tags: [t('Перевірка точності', 'Accuracy checks'), t('Калібрування', 'Calibration')], prerequisites: ['machine-alignment', 'backlash-leadscrews', 'inspection-plan'],
    hazards: [t('Зміна параметрів компенсації, масштабу лінійок або сервоналаштувань — сервісна робота. Не вводьте поправки за одним випадковим вимірюванням.', 'Changing compensation, scale factors or servo settings is service work. Never apply corrections from one arbitrary measurement.')],
    steps: [
      s('Встановіть мету перевірки', 'Define the verification purpose', 'Відрізніть контроль після ремонту, пошук дефекту та підтвердження придатності для конкретної деталі. Зафіксуйте потрібні характеристики й межі з OEM та завдання, а не вигадуйте єдиний клас точності.', 'Separate post-repair acceptance, fault finding and suitability for a specific part. Define characteristics and limits from the OEM and task rather than inventing one universal accuracy class.'),
      s('Перевірте вимірювальний ланцюг', 'Verify the measurement chain', 'Для еталонів і приладів потрібні придатний діапазон, невизначеність та чинний стан калібрування. Перевірка нуля штангенциркуля не калібрує вісь верстата; нестійка стійка може створити хибну похибку.', 'References and instruments need suitable range, uncertainty and calibration status. Zeroing calipers does not calibrate a machine axis; an unstable stand can create a false error.'),
      s('Зафіксуйте умови', 'Record the conditions', 'Запишіть температуру, прогрів за OEM, навантаження стола, положення осей і напрямок підходу. Порівнювати різні дні без цих даних може бути некоректно.', 'Record temperature, OEM warm-up state, table load, axis positions and approach direction. Comparing different days without these conditions may be misleading.'),
      s('Окремо виміряйте різні властивості', 'Measure each property separately', 'Виконавець перевіряє геометричні зв’язки, позиціонування й повторюваність відповідними методами. Повторення одного положення не підтверджує правильність усієї шкали; биття не тотожне прямолінійності.', 'The responsible person checks geometric relationships, positioning and repeatability using suitable methods. Repeating one position does not validate the entire scale; runout is not straightness.'),
      s('Порівняйте напрямки та повтори', 'Compare directions and repeats', 'У протоколі зберігайте всі точки, прямий і зворотний підхід та кілька повторів, якщо це передбачено методом. Розділіть систематичне зміщення, реверсний люфт і розкид; не маскуйте їх одним середнім.', 'Retain all points, forward/reverse approaches and repeated cycles where the method requires them. Separate systematic offset, reversal loss and spread rather than hiding them in one average.'),
      s('Прийміть і задокументуйте рішення', 'Decide and document', 'Кваліфікований фахівець визначає ремонт, дозволену компенсацію або обмеження застосування. Після зміни повторює перевірку. За непоясненої нестабільності верстат не допускають до завдань, точність яких не підтверджена.', 'A qualified specialist decides on repair, permitted compensation or application limits and repeats checks after changes. Do not release an unstable machine for tasks whose accuracy is unverified.', 'Кожне твердження про точність підкріплене методом, даними й межами.', 'Every accuracy claim has a method, data and limits.'),
    ], takeaways: [t('Повторюваність і точність — різні поняття.', 'Repeatability and accuracy are different properties.'), t('Калібрований прилад потрібний для перевірки, але сам не робить верстат точним.', 'A calibrated instrument supports verification but does not itself make a machine accurate.')], sources: ['mitutoyo-indicator', 'mitutoyo-guide', 'prep-haas-maintenance'],
    quiz: q('Вісь тричі повернулася в одну точку. Чи доводить це правильний масштаб на всьому ході?', 'An axis returned to one point three times. Does that prove correct scale over its full travel?', [t('Так', 'Yes'), t('Ні, це лише частина перевірки повторюваності', 'No, that is only part of a repeatability check'), t('Так, якщо дисплей цифровий', 'Yes, if the display is digital')], 1, 'Систематична похибка масштабу може бути повторюваною; її перевіряють окремо.', 'A systematic scale error can be repeatable; it requires a separate check.'),
  }),
  care({
    id: 'tool-setting-lathe', title: t('Встановлення та прив’язка токарного різця', 'Set and reference a turning tool'), summary: t('Перевіряємо тримач, висоту вершини, орієнтацію, виліт і координатну прив’язку перед різанням.', 'Check the holder, tip height, orientation, overhang and coordinate reference before cutting.'), minutes: 13, level: 'intermediate', tags: [t('Налаштування різця', 'Tool setting'), t('Токарний', 'Lathe')], prerequisites: ['daily-inspection', 'lathe-setup', 'turning-tools'], model: 'lathe',
    hazards: [t('Не регулюйте різець, не підсовуйте шаблон і не затягуйте тримач при обертанні. Зміна висоти або вильоту змінює зазори й потребує повторної перевірки.', 'Do not adjust a tool, introduce a gauge or tighten a holder during rotation. Height or overhang changes alter clearance and require rechecking.')],
    steps: [
      s('Звірте різець із операцією', 'Match the tool to the operation', 'Підтвердьте напрямок різання, правий або лівий тримач, потрібний доступ до торця чи уступу та сумісність пластини. Налаштування не перетворює непридатну геометрію на придатну.', 'Confirm cutting direction, right- or left-hand holder, face or shoulder access and insert compatibility. Setting cannot turn an unsuitable geometry into a suitable one.'),
      s('Підготуйте чисті посадки', 'Prepare clean seats', 'За повної зупинки й потрібної ізоляції очистіть різцетримач, опору й посадку пластини. Перевірте кріпильний елемент, притиск і відсутність тріщин; пошкоджені деталі вилучіть, а не компенсуйте сильнішим затягуванням.', 'With motion stopped and required isolation applied, clean the toolpost, support and insert seat. Check the fastener, clamp and cracks; retire damaged components rather than overtightening them.'),
      s('Визначте виліт і підтримку', 'Set overhang and support', 'Залиште мінімальний достатній виліт для доступу та відводу стружки. Переріз тримача має відповідати різцетримачу. Підкладки допускаються лише у придатній стабільній конфігурації, а не випадковою тонкою купкою.', 'Use the shortest overhang that provides access and chip clearance. The shank must suit the toolpost. Use shims only in a suitable stable arrangement, never an arbitrary loose stack.'),
      s('Виставте вершину дозволеним методом', 'Set tip height by the approved method', 'Наставник задає висоту відносно осі шпинделя для цієї операції, користуючись відповідним калібром або іншим методом OEM. Перевірте також кут тримача та бокові зазори; порівняння з неперевіреним центром недостатнє.', 'The supervisor establishes tip height relative to spindle center for this operation using a suitable gauge or OEM method. Also check holder angle and side clearances; comparison to an unverified center is insufficient.'),
      s('Закріпіть і перевірте весь маршрут', 'Secure and check the full path', 'Затягніть за документацією тримача й повторно перевірте висоту. На безпечно зупиненому верстаті оцініть зазори до кулачків, центра, уступів і тримача на всьому маршруті; приберіть калібри й ключі.', 'Tighten under the holder instructions and recheck height. With the machine safely stopped, assess clearance to jaws, center, shoulders and holder over the full path; remove gauges and keys.'),
      s('Прив’яжіть і підтвердіть результат', 'Reference and verify', 'Для ручного верстата запишіть відлік і спосіб підходу; для ЧПУ виконайте штатну прив’язку та перевірку регістру. Перший контрольований різ — лише після перевірки наставником; відхилення або вібрація означають зупинку.', 'For a manual lathe, record the reference and approach method; for CNC, use the supported referencing and register check. Make the first controlled cut only after supervisor approval; stop for deviations or chatter.', 'Висота, виліт, затиск і прив’язка перевірені після фіксації.', 'Height, overhang, clamping and reference are verified after securing.'),
    ], takeaways: [t('Висота вершини й кут тримача впливають на фактичну геометрію різання.', 'Tip height and holder angle affect the actual cutting geometry.'), t('Після заміни пластини, тримача чи вильоту прив’язку перевіряють знову.', 'Recheck the reference after changing the insert, holder or overhang.')], sources: ['tool-sandvik-lathe-setup', 'haas-lathe', 'ccohs-lathe'],
    quiz: q('Після зміни вильоту різця можна одразу продовжувати?', 'May you immediately resume after changing tool overhang?', [t('Так, матеріал той самий', 'Yes, the material is unchanged'), t('Ні, повторно перевірте затиск, зазори та прив’язку', 'No, recheck clamping, clearance and reference'), t('Так, якщо не змінювали оберти', 'Yes, if rpm is unchanged')], 1, 'Нова геометрія встановлення змінює жорсткість, межі зіткнень і координатний зв’язок.', 'The new setup geometry changes rigidity, collision limits and coordinate relationships.'),
  }),
  care({
    id: 'tool-setting-mill', title: t('Встановлення фрези, тримача та довжини', 'Set a milling cutter, holder and length'), summary: t('Сумісність конуса й цанги, чистота контакту, виліт, биття та перевірена корекція довжини.', 'Verify taper and collet compatibility, clean contact, overhang, runout and tool-length reference.'), minutes: 14, level: 'intermediate', tags: [t('Налаштування фрези', 'Cutter setting'), t('Тримач', 'Toolholder')], prerequisites: ['daily-inspection', 'mill-setup', 'milling-cutters'],
    hazards: [t('Фреза гостра навіть без обертання. Не тримайте її за кромки; зміну виконують у безпечному стані за OEM. Свердлильний патрон не стає фрезерним тримачем від сильнішого затягування.', 'A cutter is sharp even when stationary. Do not grip its cutting edges; change it in the OEM-defined safe state. Harder tightening does not make a drill chuck a milling holder.')],
    steps: [
      s('Перевірте весь інтерфейс', 'Verify the complete interface', 'Зіставте шпиндель, конус, тяговий елемент, тримач, цангу, гайку й хвостовик. Для кожного потрібні правильні типорозмір і допустимі оберти; зовнішньої схожості недостатньо.', 'Match spindle, taper, retention component, holder, collet, nut and shank. Each needs the correct size/type and speed rating; visual similarity is insufficient.'),
      s('Очистіть і огляньте', 'Clean and inspect', 'Після потрібної ізоляції очистіть посадки й огляньте цангу, різьбу, контактні поверхні та інструмент. Не затискайте по стружці, задирці чи різальній канавці; дефектну цангу замініть.', 'After required isolation, clean seats and inspect collet, thread, contact faces and tool. Do not clamp over chips, burrs or flutes; replace a defective collet.'),
      s('Задайте достатній короткий виліт', 'Set sufficient short overhang', 'Обчисліть потрібний доступ до дна й стінок із запасом для тримача. Хвостовик має захоплюватися на довжину, визначену виробником; фрезу не висувають довільно для обходу затискача.', 'Determine reach to floor and walls with holder clearance. Grip the shank over the manufacturer-specified length; do not arbitrarily extend the cutter to bypass a clamp.'),
      s('Складіть і затягніть за OEM', 'Assemble and tighten under the OEM', 'Послідовність встановлення цанги та момент залежать від системи. Використайте призначений ключ і, де потрібно, монтажний пристрій; не бийте по інструменту й не використовуйте небезпечні подовжувачі.', 'Collet assembly sequence and torque depend on the system. Use the specified wrench and mounting fixture where required; do not hammer tooling or use unsafe wrench extensions.'),
      s('Перевірте биття та довжину', 'Check runout and length', 'Навчена людина виконує контроль визначеної поверхні й встановлення довжини дозволеним способом. Запишіть вимірювальну точку та регістр. Не запускайте шпиндель із залишеним індикатором або ключем.', 'A trained person checks the specified surface and sets length by the approved method. Record the measuring point and register. Do not start the spindle with an indicator or wrench left in place.'),
      s('Перевірте прив’язку перед різанням', 'Verify the reference before cutting', 'Переконайтеся, що номер інструмента, діаметр, довжина й активна компенсація відповідають програмі або карті ручної обробки. Наставник перевіряє зазори; за неможливості надійного затиску або надмірного биття — зупинка й заміна/сервіс.', 'Confirm tool number, diameter, length and active compensation match the program or manual setup sheet. Have the supervisor check clearances; stop for insecure grip or excessive runout and replace or service the assembly.', 'Фреза надійно утримується; довжина й регістр перевірені.', 'The cutter is securely held; length and register are verified.'),
    ], takeaways: [t('Довжина інструмента описує всю зібрану систему, а не лише фрезу.', 'Tool length describes the entire assembly, not just the cutter.'), t('Надмірний виліт погіршує жорсткість навіть з дорогим інструментом.', 'Excessive overhang reduces rigidity even with an expensive cutter.')], sources: ['tool-sandvik-holders', 'haas-setup', 'prep-haas-desktop'],
    quiz: q('Чому після заміни цанги потрібно перевірити інструмент повторно?', 'Why must the tool be checked again after changing a collet?', [t('Могли змінитися захоплення, биття й фактична довжина', 'Grip, runout and actual length may have changed'), t('Це потрібно лише для нового кольору фрези', 'Only the cutter color matters'), t('Перевірка не потрібна', 'No check is needed')], 0, 'Змінено частину вимірювального й силового ланцюга; попередня прив’язка не є достатнім доказом.', 'Part of the measuring and load path has changed; the old reference is insufficient proof.'),
  }),
  tooling({
    id: 'tooling-requirements', title: t('Вибір інструмента починається із завдання', 'Start tool selection from the task'), summary: t('Створюємо картку вибору: геометрія деталі, матеріал, операція, точність, верстат, кріплення та контроль.', 'Build a selection sheet covering part geometry, material, operation, accuracy, machine, workholding and inspection.'), minutes: 12, level: 'beginner', tags: [t('Вибір інструмента', 'Tool selection'), t('Планування', 'Planning')], prerequisites: ['machine-assessment', 'technical-drawing', 'material-identification'],
    hazards: [t('Відповідний діаметр не доводить придатності інструмента. Не запускайте невідомий інструмент без даних про матеріал, кріплення, напрямок, допустимі оберти й операцію.', 'A matching diameter does not establish tool suitability. Do not run an unidentified tool without material, holding, direction, speed-rating and operation data.')],
    steps: [
      s('Опишіть потрібну ознаку', 'Describe the required feature', 'Запишіть площину, уступ, паз, отвір або різьбу, доступ, глибину, внутрішні радіуси та потрібну поверхню. Розділіть чорнове знімання й фініш; одна фреза не обов’язково має виконати все.', 'List the face, shoulder, slot, bore or thread, access, depth, internal radii and finish. Separate roughing and finishing; one cutter need not perform every operation.'),
      s('Підтвердіть матеріал і стан', 'Confirm material and condition', 'Внесіть точну марку, твердість або стан постачання та покриття. «Сталь» або «алюміній» — надто широкі визначення для остаточного вибору геометрії, марки кромки й режиму.', 'Record exact grade, hardness or supply condition and coating. Steel or aluminum alone is too broad for final geometry, cutting-grade and condition selection.'),
      s('Перевірте можливості верстата', 'Check machine capability', 'Врахуйте діапазон обертів, доступний крутний момент, потужність на цих обертах, жорсткість, люфт і дозволений тип подачі. Інструмент для жорсткого ЧПУ може не відповідати легкому ручному верстату.', 'Consider speed range, available torque, power at that speed, rigidity, backlash and permitted feed method. Tooling intended for a rigid CNC machine may not suit a light manual machine.'),
      s('Зіставте кріплення та досяжність', 'Match holding and reach', 'Підберіть сумісний хвостовик і тримач, достатню різальну довжину та короткий виліт. Перевірте прохід тримача над затисками й те, чи вистачить опори заготовки після знімання матеріалу.', 'Choose a compatible shank and holder, sufficient cutting length and short overhang. Check holder clearance above clamps and whether work support remains after material removal.'),
      s('Порівняйте дані виробника', 'Compare manufacturer data', 'Для кандидатів звірте призначені матеріали, операції, обмеження входу, відведення стружки й вимоги до рідини. Початкові режими мають бути для конкретного коду інструмента, а не для фотографії схожої фрези.', 'Compare intended materials, operations, entry limits, chip evacuation and fluid requirements. Starting conditions must apply to the exact tool code rather than a photograph of a similar cutter.'),
      s('Визначте критерій перевірки', 'Define how selection will be verified', 'До покупки або встановлення запишіть, чим підтвердите розмір і які ознаки вимагатимуть зупинки. Першу навчальну операцію погодьте з наставником; невідповідний інтерфейс, незрозуміла марка чи брак даних означають відкладений запуск.', 'Before purchase or installation, record how size will be verified and what requires stopping. Agree the first learning operation with a supervisor; incompatible interfaces, unknown grade or missing data mean no start.', 'Картка пояснює вибір і перевірку, а не лише назву інструмента.', 'The sheet explains the choice and verification, not just the tool name.'),
    ], takeaways: [t('Інструмент добирають до системи «деталь — матеріал — операція — верстат».', 'Select tooling for the part–material–operation–machine system.'), t('План контролю впливає на вибір технології так само, як потрібний діаметр.', 'Inspection requirements influence process selection as much as the nominal diameter.')], sources: ['tool-sandvik-milling', 'tool-sandvik-drilling', 'tool-sandvik-holders'],
    quiz: q('Що потрібно вказати разом із запитом «фреза Ø10»?', 'What must accompany a request for a Ø10 cutter?', [t('Лише бажаний колір покриття', 'Only the desired coating color'), t('Матеріал, операцію, глибину, точність, тримач і можливості верстата', 'Material, operation, depth, accuracy, holder and machine capability'), t('Лише кількість у пачці', 'Only pack quantity')], 1, 'Сам діаметр не задає доступ, геометрію, матеріал кромки або допустиму операцію.', 'Diameter alone does not define reach, geometry, cutting material or permitted operation.'),
  }),
  tooling({
    id: 'tooling-materials', title: t('HSS, твердий сплав, геометрія та покриття', 'HSS, carbide, geometry and coatings'), summary: t('Обираємо матеріал кромки й геометрію під сплав заготовки та жорсткість встановлення.', 'Match cutting material and geometry to the work alloy and setup rigidity.'), minutes: 13, level: 'intermediate', tags: [t('Матеріал інструмента', 'Cutting material'), t('Покриття', 'Coating')], prerequisites: ['tooling-requirements'],
    hazards: [t('Крихка кромка може сколотися й вилетіти. Новачок не переточує твердосплавні інструменти: потрібні спеціальне обладнання, пиловидалення та навчання.', 'A brittle edge can chip and eject fragments. Beginners must not regrind carbide tools; specialized equipment, dust controls and training are required.')],
    steps: [
      s('Відокремте основу від покриття', 'Separate substrate from coating', 'HSS — швидкорізальна сталь, твердий сплав — інша група різальних матеріалів; тонке покриття не визначає основу. Визначайте інструмент за маркуванням і каталогом, а не золотистим чи темним кольором.', 'HSS is high-speed steel; carbide is a different cutting-material group. A thin coating does not identify the substrate. Use marking and catalog data, not a gold or dark color.'),
      s('Зіставте міцність і режим роботи', 'Match toughness and operating conditions', 'HSS часто краще переносить удар і менш жорсткі умови, але має свої теплові обмеження. Твердий сплав може працювати продуктивно за відповідних швидкості й жорсткості, проте не є автоматично кращим для кожного настільного верстата.', 'HSS often tolerates shock and less-rigid conditions better but has thermal limits. Carbide can perform productively with suitable speed and rigidity, but is not automatically better on every benchtop machine.'),
      s('Уточніть сплав і оброблюваність', 'Identify alloy and machinability', 'Сталі, нержавійки, чавуни, кольорові, жароміцні та загартовані матеріали потребують різних рекомендацій. Усередині групи важливі марка, твердість і стан; назва групи лише початковий фільтр.', 'Steels, stainless steels, cast irons, nonferrous, heat-resistant and hardened materials need different recommendations. Grade, hardness and condition still matter within each group; the group is only an initial filter.'),
      s('Оберіть геометрію кромки', 'Select edge geometry', 'Порівняйте гостроту, передній кут, зміцнення кромки, стружколам і об’єм канавок. Гостріша геометрія може знижувати сили, але зменшувати міцність; рішення залежить від безперервного чи переривчастого різу й опори деталі.', 'Compare sharpness, rake, edge preparation, chipbreaker and flute space. Sharper geometry may reduce forces but sacrifice strength; the choice depends on continuous/interrupted cutting and work support.'),
      s('Перевірте покриття й рідину за каталогом', 'Verify coating and fluid compatibility', 'Покриття має бути рекомендоване для конкретного матеріалу й режиму. Не переносіть придатність для сталі на алюміній або пластик. Окремо перевірте сумісність рідини та правила вентиляції за SDS.', 'The coating must be recommended for the specific material and conditions. Do not transfer steel suitability to aluminum or plastic. Separately verify fluid compatibility and SDS ventilation requirements.'),
      s('Запишіть обґрунтований комплект', 'Record the justified combination', 'Збережіть код основи/марки, покриття, геометрії й джерело даних. Наставник перевіряє стартовий процес; за сколів, налипання, плавлення чи перегріву зупиніться й перегляньте всю систему, а не лише оберти.', 'Record substrate/grade, coating, geometry codes and data source. Have the supervisor approve the starting process; stop for chipping, adhesion, melting or overheating and reassess the whole system rather than rpm alone.', 'Основа, геометрія й покриття відповідають матеріалу та умовам.', 'Substrate, geometry and coating match the material and conditions.'),
    ], takeaways: [t('Колір покриття не є специфікацією.', 'Coating color is not a specification.'), t('Жорсткість і ударні навантаження впливають на вибір матеріалу кромки.', 'Rigidity and shock loading influence cutting-material selection.')], sources: ['sandvik-materials', 'tool-sandvik-inserts', 'tool-sandvik-condition'],
    quiz: q('Чи завжди твердосплавна фреза краща за HSS?', 'Is a carbide end mill always better than HSS?', [t('Так, незалежно від встановлення', 'Yes, regardless of setup'), t('Ні, вибір залежить від матеріалу, швидкості, жорсткості й навантажень', 'No, it depends on material, speed, rigidity and loading'), t('Так, якщо покриття темне', 'Yes, if the coating is dark')], 1, 'Матеріал кромки — лише один елемент узгодженої різальної системи.', 'Cutting material is only one element of a matched cutting system.'),
  }),
  tooling({
    id: 'turning-tools', title: t('Як вибрати токарний різець і пластину', 'Choose a turning tool and insert'), summary: t('Операція, доступ, напрямок, форма й радіус пластини, марка та сумісний тримач.', 'Match operation, access, hand, insert shape and radius, grade and compatible holder.'), minutes: 14, level: 'intermediate', tags: [t('Токарний різець', 'Turning tool'), t('Пластина', 'Insert')], prerequisites: ['tooling-materials', 'workholding-basics'], model: 'shaft',
    hazards: [t('Схожа пластина не обов’язково підходить до гнізда. Не ставте інший розмір, товщину, отвір або притиск і не затягуйте випадковим гвинтом.', 'A similar-looking insert may not fit the pocket. Never substitute size, thickness, hole or clamp type or use an arbitrary screw.')],
    steps: [
      s('Назвіть операцію та потрібний доступ', 'Define operation and access', 'Розділіть поздовжнє точіння, торцювання, профіль, розточування, канавку та відрізання. Перевірте найменший внутрішній радіус, кут уступу й місце для корпусу різця; не застосовуйте загальний різець для спеціальної канавки.', 'Separate longitudinal turning, facing, profiling, boring, grooving and parting. Check the smallest internal radius, shoulder angle and holder-body access; do not use a general turning tool for a specialized groove.'),
      s('Визначте напрямок і корпус', 'Choose hand and holder', 'За схемою виробника оберіть правий, лівий або нейтральний різець і напрямок подачі. Переріз хвостовика, довжина й затиск мають відповідати верстату; для розточування потрібні доступний діаметр і короткий достатній виліт.', 'Use the manufacturer’s diagram to choose right-, left- or neutral-hand tooling and feed direction. Shank section, length and clamping must suit the machine; boring also needs adequate bore access and short sufficient overhang.'),
      s('Зіставте форму та радіус із деталлю', 'Match shape and nose radius to the part', 'Міцніша форма й більший радіус не завжди вигідні: вони можуть обмежити доступ і збільшити радіальні сили. Радіус вершини має бути сумісним із переходом деталі, глибиною, подачею та жорсткістю.', 'A stronger shape and larger radius are not always advantageous: they may restrict access and increase radial force. Match nose radius to the part transition, depth, feed and rigidity.'),
      s('Доберіть геометрію та марку', 'Select geometry and grade', 'Виберіть стружколам і геометрію для чорнового чи чистового процесу, матеріалу й переривчастості різу. Позитивна геометрія часто зменшує сили, але її міцність і робочий діапазон також потрібно перевірити.', 'Select chipbreaker and geometry for roughing/finishing, work material and interrupted conditions. Positive geometry often reduces forces, but its strength and operating window must also be checked.'),
      s('Перевірте точну сумісність', 'Verify exact compatibility', 'Звірте повний код пластини, гніздо, підкладну пластину, притиск і гвинт із каталогом тримача. Огляньте поверхні; сколи гнізда чи пошкоджена різьба потребують заміни або сервісу, а не додаткового моменту.', 'Match the complete insert code, pocket, shim, clamp and screw to the holder catalog. Inspect contact surfaces; a chipped pocket or damaged thread needs replacement or service, not extra torque.'),
      s('Підготуйте налаштування та пробу', 'Prepare setting and trial', 'Передайте вибраний комплект до інструкції встановлення токарного різця. З наставником погодьте висоту, виліт, режим і контроль першої деталі. Небажані довгі витки, вібрація або сколи — причина зупинити процес і переоцінити вибір.', 'Use the turning-tool setting procedure for the chosen assembly. Agree height, overhang, conditions and first-part inspection with your supervisor. Unwanted long coils, chatter or chipping require stopping and reassessing the choice.', 'Коди й геометрія узгоджені; заплановані налаштування та контроль.', 'Codes and geometry agree; setting and inspection are planned.'),
    ], takeaways: [t('Радіус вершини вибирають разом із жорсткістю й геометрією деталі.', 'Choose nose radius together with rigidity and part geometry.'), t('Тримач і пластина — сумісний комплект із власними обмеженнями.', 'The holder and insert are a matched assembly with their own limits.')], sources: ['tool-sandvik-inserts', 'tool-sandvik-lathe-setup', 'sandvik-external'],
    quiz: q('Чому не слід автоматично обирати найбільший радіус вершини?', 'Why should you not automatically choose the largest nose radius?', [t('Він може не пройти в кут і збільшити сили на нежорсткій деталі', 'It may not reach a corner and may increase forces on flexible work'), t('Великий радіус завжди зменшує всі сили', 'A large radius always reduces every force'), t('Радіус не впливає на процес', 'Radius has no process effect')], 0, 'Міцність кромки, доступ і сили потребують узгодженого компромісу.', 'Edge strength, access and forces require a matched compromise.'),
  }),
  tooling({
    id: 'milling-cutters', title: t('Вибір фрези: площина, уступ, паз, кишеня', 'Choose cutters for faces, shoulders, slots and pockets'), summary: t('Порівнюємо форму, діаметр, робочу довжину, канавки й спосіб входу в матеріал.', 'Compare shape, diameter, cutting length, flutes and entry into the material.'), minutes: 15, level: 'intermediate', tags: [t('Фреза', 'Milling cutter'), t('Паз і кишеня', 'Slot and pocket')], prerequisites: ['tooling-materials', 'workholding-basics'], model: 'pocket',
    hazards: [t('Не кожна фреза ріже центром і допускає пряме врізання. Бокове фрезерування, повний паз і осьове врізання мають різні навантаження та обмеження.', 'Not every cutter cuts at center or permits direct plunging. Side milling, full-slot cutting and axial entry have different loads and limits.')],
    steps: [
      s('Зіставте тип із поверхнею', 'Match cutter type to the feature', 'Для площини, прямого уступу, паза, кишені та об’ємного профілю можуть знадобитися різні форми. Кульова фреза формує радіус і має змінний ефективний діаметр, тому не є прямою заміною плоскої кінцевої.', 'Faces, square shoulders, slots, pockets and 3D profiles may need different shapes. A ball nose forms a radius and has a changing effective cutting diameter, so it is not a direct substitute for a flat end mill.'),
      s('Перевірте діаметр і кути', 'Check diameter and corners', 'Діаметр має пройти в геометрію з урахуванням траєкторії й потрібного радіуса. Внутрішній кут після круглої фрези не стане гострим. Не обирайте фрезу за шириною паза без оцінки биття та потрібної чистової стратегії.', 'The diameter must fit the geometry, path and required radius. A round cutter cannot leave a sharp internal corner. Do not select solely by slot width without considering runout and a finishing strategy.'),
      s('Виберіть робочу довжину й досяжність', 'Choose cutting length and reach', 'Різальна частина має обробити потрібну глибину, а шийка й тримач — пройти повз стінки та кріплення. Зайва довжина послаблює систему; довший хвостовик не означає довшу придатну різальну частину.', 'The flutes must cover the required cut, while neck and holder clear walls and clamps. Extra length weakens the system; a longer shank does not imply a longer usable cutting section.'),
      s('Порівняйте канавки й матеріал', 'Compare flutes and material needs', 'Кількість зубів, простір для стружки, спіраль, геометрія й покриття обираються разом. Не застосовуйте універсальне правило «більше зубів — краще» або одну кількість для всіх сплавів.', 'Select tooth count, chip space, helix, geometry and coating together. Do not apply a universal more-teeth-is-better rule or one flute count for every alloy.'),
      s('Перевірте спосіб входу та охоплення', 'Verify entry and engagement', 'Каталог має дозволяти вибрані врізання, рампу або вхід через попередній отвір. Для повного паза перевірте окремі дані; режим легкого бокового проходу не переноситься автоматично. Урахуйте люфт ручного верстата.', 'The catalog must permit the selected plunge, ramp or predrilled entry. Use separate full-slot data; light side-cut conditions do not transfer automatically. Account for backlash on a manual machine.'),
      s('Узгодьте комплект і контроль', 'Approve the assembly and inspection', 'Перевірте сумісність тримача, виліт, оберти та стружковідведення за інструкцією встановлення фрези. Наставник підтверджує процес. За контакту тримача, забивання канавок або вібрації — зупинка, очищення в безпечному стані й перегляд плану.', 'Verify holder compatibility, overhang, speed and chip removal under the cutter-setting procedure. Have the supervisor approve the process. Stop for holder contact, packed flutes or chatter; clean in the safe state and revise the plan.', 'Фреза проходить у геометрію; вхід і режим дозволені виробником.', 'The cutter fits the geometry and the manufacturer permits entry and cutting conditions.'),
    ], takeaways: [t('Діаметр, канавки та робоча довжина — лише частина специфікації.', 'Diameter, flutes and cutting length are only part of the specification.'), t('Правильний вибір має враховувати тримач і весь маршрут.', 'A correct choice includes the holder and the complete path.')], sources: ['tool-sandvik-milling', 'tool-sandvik-shoulder', 'tool-sandvik-slot'],
    quiz: q('Що перевірити перед прямим врізанням кінцевої фрези?', 'What must you check before plunging an end mill?', [t('Чи дозволяє виробник різання центром і цей спосіб входу', 'Whether the manufacturer permits center cutting and this entry method'), t('Лише чи влазить діаметр у паз', 'Only whether the diameter fits the slot'), t('Лише кількість зубів', 'Only the number of flutes')], 0, 'Здатність бокового різання не підтверджує здатності безпечно врізатися по осі.', 'Side-cutting capability does not establish safe axial-entry capability.'),
  }),
  tooling({
    id: 'drilling-tools', title: t('Вибір свердла та підготовки отвору', 'Choose a drill and hole preparation'), summary: t('Діаметр, глибина, глухий чи наскрізний отвір, матеріал, точність і доступ визначають потрібний процес.', 'Diameter, depth, blind or through form, material, accuracy and access determine the drilling process.'), minutes: 14, level: 'intermediate', tags: [t('Свердло', 'Drill'), t('Отвір', 'Hole')], prerequisites: ['tooling-materials', 'workholding-basics'],
    hazards: [t('Довге свердло гнеться легше, а глибокий отвір ускладнює відведення стружки. Не переносіть метод короткого отвору на глибокий без спеціальної технології.', 'A long drill deflects more readily and a deep hole complicates chip evacuation. Do not transfer a short-hole process to deep drilling without a specific procedure.')],
    steps: [
      s('Опишіть отвір повністю', 'Describe the complete hole', 'Запишіть діаметр, повну циліндричну глибину, вхід, вихід, дно, перехресні отвори й вимоги до положення. Розділіть глибину до вершини свердла та до повного діаметра.', 'Record diameter, full-diameter depth, entry, exit, bottom, cross holes and location requirements. Separate drill-tip depth from full-diameter depth.'),
      s('Визначте фінішний маршрут', 'Define the finishing route', 'Для простого зазору під болт свердління може бути достатнім після контролю. Для точної посадки, положення чи поверхні заплануйте потрібне розточування або розгортання; свердло само по собі не гарантує всіх вимог.', 'Drilling may suffice for a simple bolt-clearance hole after inspection. For a precision fit, position or finish, plan appropriate boring or reaming; a drill alone does not guarantee every requirement.'),
      s('Доберіть конструкцію під матеріал і верстат', 'Match construction to material and machine', 'Оберіть HSS, твердий сплав чи іншу рекомендовану систему з геометрією для матеріалу й потрібною жорсткістю. Перевірте хвостовик, патрон або цангу, потужність і момент; не затискайте по канавках.', 'Select HSS, carbide or another recommended system with geometry for the material and required rigidity. Verify shank, chuck or collet, power and torque; never grip the flutes.'),
      s('Використайте найкоротший придатний інструмент', 'Use the shortest suitable drill', 'Довжина повинна забезпечувати глибину, вихід і відведення стружки без зайвого вильоту. Стартове центрування та пілотний отвір застосовуйте лише в сумісній із конкретним свердлом геометрії; вони не універсально потрібні.', 'Length must allow depth, breakthrough and chip evacuation without unnecessary overhang. Use spotting or a pilot only in geometry compatible with the exact drill; neither is universally required.'),
      s('Перевірте охолодження та цикл', 'Check fluid and cycle requirements', 'З каталогу визначте потрібні подачу рідини, режими й допустимий спосіб відведення стружки. Не додавайте довільні багаторазові виходи для будь-якого твердосплавного свердла: цикл залежить від конструкції та матеріалу.', 'Use the catalog for required fluid delivery, conditions and permitted chip-removal method. Do not add arbitrary repeated withdrawals to every carbide drill; the cycle depends on construction and material.'),
      s('Погодьте кріплення та пробний контроль', 'Approve holding and trial inspection', 'Закріпіть деталь і пристрій, перевірте підкладку, вихід і глибину за відповідною інструкцією. Наставник підтверджує процес; при скрипі, забиванні, наростанні зусилля чи зміщенні — зупинка, а не сильніше натискання.', 'Secure both work and fixture and check backing, breakthrough and depth under the relevant procedure. Have the supervisor approve the process; stop for squealing, packing, rising force or movement rather than pushing harder.', 'Підготовка, глибина й контроль відповідають конкретному свердлу.', 'Preparation, depth and inspection match the specific drill.'),
    ], takeaways: [t('Коротке свердло часто дає жорсткішу систему, якщо його вистачає для завдання.', 'A shorter drill often gives a stiffer system when it provides sufficient reach.'), t('Призначення отвору визначає, чи потрібна окрема фінішна операція.', 'The hole’s purpose determines whether a separate finishing operation is required.')], sources: ['tool-sandvik-drilling', 'tool-sandvik-condition', 'ccohs-drill'],
    quiz: q('Чи потрібен пілотний отвір перед будь-яким свердлом?', 'Does every drill require a pilot hole?', [t('Так, без винятку', 'Yes, without exception'), t('Ні, це визначає конструкція свердла й технологія', 'No, the drill design and process define the need'), t('Так, якщо верстат малопотужний', 'Yes, whenever machine power is low')], 1, 'Несумісний пілот або кут початкового центрування може погіршити роботу певного свердла.', 'An incompatible pilot or spotting angle can worsen the behavior of a particular drill.'),
  }),
  tooling({
    id: 'threading-reaming', title: t('Мітчики, різьбові інструменти та розгортки', 'Taps, threading tools and reamers'), summary: t('Розрізняємо створення різьби та фініш отвору, вибираємо підготовку й контроль замість універсальних формул.', 'Separate thread generation from hole finishing and choose preparation and inspection instead of universal formulas.'), minutes: 16, level: 'advanced', tags: [t('Мітчик', 'Tap'), t('Розгортка', 'Reamer')], prerequisites: ['drilling-tools', 'inspection-plan'],
    hazards: [t('Мітчик і розгортка можуть заклинити й зламатися. Не утримуйте деталь рукою, не вгадуйте підготовчий діаметр і не застосовуйте автоматичний цикл без навчання на конкретному контролері.', 'Taps and reamers can seize and break. Do not hold work by hand, guess the prepared diameter or run an automatic cycle without training on the exact controller.')],
    steps: [
      s('Розділіть дві різні цілі', 'Separate the two objectives', 'Мітчик утворює різьбу, розгортка фінішує вже наявний отвір. Для різьби задайте стандарт, профіль, крок, напрямок і поле допуску; для гладкого отвору — розмір, форму, положення та поверхню.', 'A tap generates a thread; a reamer finishes an existing bore. Specify thread standard, profile, pitch, hand and tolerance class; for a plain bore, specify size, form, position and finish.'),
      s('Оберіть тип мітчика', 'Choose the tap type', 'Різальний і формувальний мітчики потребують різної підготовки та придатності матеріалу. Наскрізний і глухий отвори вимагають узгодженого напрямку відведення стружки й достатнього місця для заходу інструмента.', 'Cutting and forming taps need different preparation and material suitability. Through and blind holes need matched chip-flow direction and enough allowance for the tool’s lead section.'),
      s('Визначте підготовчий отвір за даними інструмента', 'Specify the prepared hole from tool data', 'Діаметр, глибину свердління й запас за повною різьбою беріть із таблиці для конкретного мітчика, матеріалу та стандарту. Побутове «діаметр мінус крок» не є універсальною технологією, особливо для формування.', 'Take drill diameter, depth and clearance beyond full thread from data for the exact tap, material and standard. Diameter minus pitch is not a universal process, especially for forming taps.'),
      s('Для розгортки задайте припуск і вісь', 'Define reaming allowance and the existing axis', 'Розгортці потрібний припуск у діапазоні для конкретного діаметра, матеріалу й конструкції. Вона переважно слідує наявному отвору; не розраховуйте виправити значну похибку положення чи прямолінійності без іншої підготовки.', 'A reamer needs allowance suited to its diameter, material and construction. It largely follows the existing hole; do not expect it to correct substantial position or straightness error without other preparation.'),
      s('Перевірте тримач, співвісність і рух', 'Check holder, alignment and motion', 'З наставником доберіть дозволений тримач, спосіб узгодження подачі з обертанням для різьби та процедуру виведення. Ручне нарізання вимагає направлення й затиску; ЧПУ-цикл — перевірених корекцій, глибини й можливостей верстата.', 'With the supervisor, select the permitted holder, feed/rotation coordination for threading and withdrawal procedure. Hand tapping needs guidance and clamping; CNC needs verified offsets, depth and machine capability.'),
      s('Контролюйте фактичний результат', 'Inspect the actual result', 'Після безпечного завершення очистіть і перевірте отвір придатними засобами: різьбовими калібрами або вимірюванням за вимогами, гладкий отвір — відповідним приладом. Номінал розгортки й пробний болт не підтверджують усіх параметрів; при заклинюванні зупиніться й залучіть наставника.', 'After safe completion, clean and inspect with suitable methods: thread gauges or required measurement, and an appropriate instrument for the plain bore. Reamer nominal size and a trial bolt do not verify every requirement; stop and involve the supervisor if binding occurs.', 'Підготовка й контроль визначені окремо для різьби та гладкого отвору.', 'Preparation and inspection are defined separately for threads and plain bores.'),
    ], takeaways: [t('Припуск на розгортання та отвір під мітчик визначають за конкретним інструментом.', 'Specify reaming allowance and tap-hole preparation for the exact tool.'), t('Прохід болта не є повним контролем різьби.', 'A bolt passing through is not complete thread inspection.')], sources: ['tool-sandvik-tapping', 'tool-sandvik-boring', 'tool-sandvik-drilling'],
    quiz: q('Чи виправляє розгортка будь-яке зміщення осі отвору?', 'Can a reamer correct any hole-axis displacement?', [t('Так, вона завжди створює нову правильну вісь', 'Yes, it always generates a new correct axis'), t('Ні, вона переважно слідує підготовленому отвору', 'No, it generally follows the prepared hole'), t('Так, якщо її номінал точний', 'Yes, if its nominal size is precise')], 1, 'Положення й прямолінійність потрібно забезпечити відповідною підготовкою та перевірити окремо.', 'Establish position and straightness through appropriate preparation and verify them separately.'),
  }),
  tooling({
    id: 'tool-condition', title: t('Огляд, знос і вибракування інструмента', 'Inspect, assess wear and retire tooling'), summary: t('Виявляємо сколи, тріщини, налипання й пошкоджені посадки; ведемо журнал заміни без небезпечного ремонту.', 'Identify chips, cracks, adhesion and damaged seats, and keep replacement records without unsafe repair.'), minutes: 12, level: 'beginner', tags: [t('Стан інструмента', 'Tool condition'), t('Знос', 'Wear')], prerequisites: ['tooling-requirements', 'energy-isolation'],
    hazards: [t('Не перевіряйте гостроту пальцем і не очищуйте різальну кромку на ходу. Твердосплавні уламки гострі; інструмент може бути гарячим після зупинки.', 'Do not test sharpness with a finger or clean a cutting edge while running. Carbide fragments are sharp and tooling may remain hot after stopping.'), t('Новачок не зварює, не паяє й не переточує пошкоджений різальний інструмент. Кваліфіковане відновлення дозволене лише для призначених конструкцій із належним пиловидаленням.', 'Beginners must not weld, braze or regrind damaged cutting tools. Qualified reconditioning is only for suitable designs with proper dust control.')],
    steps: [
      s('Ідентифікуйте інструмент і ресурс', 'Identify the tool and usage', 'Запишіть код, матеріал заготовки, операцію й попереднє використання. Інструмент без читабельного маркування або з невідомим походженням відкладіть до ідентифікації; схожість не підтверджує його допустимі межі.', 'Record code, work material, operation and prior use. Set aside tooling with unreadable identification or unknown origin until identified; resemblance does not establish its limits.'),
      s('Зупиніть, ізолюйте й охолодіть', 'Stop, isolate and allow cooling', 'Змінюйте й оглядайте інструмент у визначеному OEM безпечному стані. Забезпечте утримання важкого тримача й захист від гострих кромок. Перед поверненням до обертання приберіть рукавички та допоміжні засоби.', 'Inspect and change tooling in the OEM-defined safe state. Support heavy holders and protect against sharp edges. Remove gloves and handling aids before returning to rotation.'),
      s('Очистіть без пошкодження', 'Clean without damage', 'Використайте сумісний засіб і спосіб із документації. Не відколюйте налипання металевим ударним інструментом і не маскуйте тріщини поліруванням. Осад та охолоджувальна рідина можуть приховувати дефект.', 'Use a compatible documented cleaning method. Do not chip off deposits with a striking metal tool or conceal cracks by polishing. Deposits and coolant can hide defects.'),
      s('Огляньте кромку та весь силовий ланцюг', 'Inspect the edge and the full load path', 'При доброму світлі й, за потреби, збільшенні перевірте сколи, тріщини, нерівномірний знос, налипання, хвостовик, цангу й посадку. Відрізняйте втрату кромки від зношеного або розбитого тримача.', 'Under good lighting and magnification where needed, inspect chipping, cracks, uneven wear, adhesion, shank, collet and seat. Distinguish edge failure from a worn or damaged holder.'),
      s('Прийміть рішення за критеріями виробника', 'Decide using manufacturer criteria', 'Тріщини, відсутній фрагмент або пошкоджене кріплення — причина вилучити інструмент. Планову межу зносу визначають за конструкцією та вимогами деталі. Пластину індексуйте лише за наявності придатної цілої кромки й сумісного справного гнізда.', 'Cracks, missing fragments or damaged retention require removal from service. Planned wear limits depend on design and part requirements. Index an insert only when a sound usable edge and compatible intact pocket remain.'),
      s('Запишіть причину й перевірте заміну', 'Record the cause and verify replacement', 'Збережіть фото й дані про умови; повторні сколи потребують перевірки затиску, биття, режиму й матеріалу з наставником. Після заміни повторіть налаштування, прив’язку та контроль першої деталі; не повторюйте той самий збій наосліп.', 'Retain photos and conditions; repeated chipping needs a supervised review of holding, runout, conditions and material. After replacement, repeat setting, referencing and first-part inspection rather than blindly repeating the failure.', 'Рішення про заміну записане; нове встановлення перевірене.', 'Replacement disposition is recorded and the new setup verified.'),
    ], takeaways: [t('Дефект тримача не лікується новою пластиною.', 'A new insert does not repair a defective holder.'), t('Історія зносу допомагає знайти причину та запланувати заміну до відмови.', 'Wear history helps identify causes and schedule replacement before failure.')], sources: ['tool-sandvik-condition', 'sandvik-turning', 'ccohs-general'],
    quiz: q('Нова пластина знову скололася в тому самому місці. Що робити?', 'A new insert chips again at the same location. What should you do?', [t('Ставити нові пластини без змін', 'Keep fitting new inserts without changes'), t('Зупинитися й перевірити причину в усій різальній системі', 'Stop and investigate the whole cutting system'), t('Збільшити затягування понад норму', 'Tighten beyond the specified limit')], 1, 'Повторний збій може бути наслідком биття, слабкого затиску, помилки траєкторії чи невідповідних умов.', 'Repeated failure may result from runout, weak clamping, path errors or unsuitable conditions.'),
  }),
];
